  // ============================================================================
  // SECTION 2  通用工具函数
  // ============================================================================
  // ===== ★v206 事件总线（deepseek-harness event-producer-consumer 移植）=====
  // 轻量 pub/sub：生产方 emit 发布事实，消费方 on 订阅；异常隔离（单个 listener 抛错
  // 不中断后续 listener、不 reject emit 调用方——对应 defensive-patterns
  // "Contain callback exceptions in the dispatcher"）。
  // 事件命名 domain/action（对齐 harness 风格）；首批事件域：
  //   writer/turn-start · writer/turn-end · writer/ops-before · writer/ops-after ·
  //   writer/op-failed · writer/card-change · writer/stream-token · writer/compact-done
  // 订阅返回取消句柄；脚本卸载时 clear() 清空全部监听。
  const _cwEvents = (function() {
    const _ls = Object.create(null);
    const _off = function(ev, fn) {
      if (!_ls[ev]) return;
      _ls[ev] = _ls[ev].filter(function(f) { return f !== fn; });
    };
    return {
      on: function(ev, fn) {
        if (typeof fn !== 'function') return function() {};
        if (!_ls[ev]) _ls[ev] = [];
        _ls[ev].push(fn);
        return function() { _off(ev, fn); };
      },
      off: _off,
      emit: function(ev, payload) {
        const arr = _ls[ev];
        if (!arr || !arr.length) return;
        for (let i = 0; i < arr.length; i++) {
          try { arr[i](payload); } catch (e) { try { console.warn('[写卡器] 事件监听器异常: ' + ev, e); } catch (_) {} }
        }
      },
      // 清空监听：ev 省略=清空全部（脚本卸载清理用）
      clear: function(ev) {
        if (ev) { _ls[ev] = undefined; }
        else { for (const k in _ls) _ls[k] = undefined; }
      }
    };
  })();
  // ===== Token估算 =====
  // ⚠️性能：CJK 正则提为模块级常量，避免 countTokens 在进度/预览循环中反复编译
  const RE_CJK = /[\u4e00-\u9fa5]/g;
  const RE_NON_CJK_SPLIT = /[\u4e00-\u9fa5]/g;

  // ===== ★v206 操作流水线（deepseek-harness tool-execution-pipeline 移植）=====
  // applyOps 四段式：pre（条目快照 + pre hooks）→ execute（applyOps 原逻辑，零改动）→
  // post（ctx.afterExecute 时机回调 + diff 计算 + 失败收集 + post hooks）→ result（冻结回执）。
  //   · ctx.afterExecute：MVU 固定资产注入等"必须在 applyOps 后、diff 前"的时序敏感逻辑——
  //     放在这里保证 diff 与 v205 行为一致（diff 含注入结果）。
  //   · hooks 接缝：hook('pre'/'post', fn) 注册扩展，第三方联动走注册而非改 applyOps 内部
  //     （对应 harness "Extend through the registered seam"）；返回注销句柄。
  //   · 回执冻结：Object.freeze(result)，消费者（ops-after 事件/UI）拿到不可变快照。
  const _opsPipeline = (function() {
    const _hooks = { pre: [], post: [] };
    return {
      hook: function(phase, fn) {
        if ((phase === 'pre' || phase === 'post') && typeof fn === 'function') {
          _hooks[phase].push(fn);
          return function() {
            const _i = _hooks[phase].indexOf(fn);
            if (_i >= 0) _hooks[phase].splice(_i, 1);
          };
        }
        return function() {};
      },
      run: function(ops, cd, ctx) {
        // ★v213 修复（运行时 ReferenceError: applyOps is not defined）：
        //   applyOps / _snapshotEntries 是外层容器函数（如 parseMessageSections）内的嵌套
        //   函数，而 _opsPipeline 是顶层 IIFE——顶层作用域链看不到嵌套函数，原直调
        //   （const raw = applyOps(ops, cd)）在真实运行环境必然抛错，导致每轮操作块
        //   执行失败并弹出"请检查酒馆是否已连接AI模型"的误导提示。
        //   修复：执行器与快照函数由调用方显式注入（调用方与 applyOps 同作用域，可见），
        //   未注入时返回明确错误回执而非 ReferenceError。
        const _exec = (ctx && typeof ctx.execute === 'function') ? ctx.execute : null;
        const _snap = (ctx && typeof ctx.snapshot === 'function') ? ctx.snapshot : null;
        // ---- pre：条目快照（applyOps 前，供 post 段 diff 对比）----
        let _entriesBefore = null;
        if (_snap) { try { _entriesBefore = _snap(); } catch (e) { logWarn('opsPipeline.pre.snapshot', e); } }
        for (let _i = 0; _i < _hooks.pre.length; _i++) {
          try { _hooks.pre[_i]({ ops: ops, cardData: cd }); } catch (e) { logWarn('opsPipeline.pre.hook', e); }
        }
        // ---- execute：注入的 applyOps（内部 40+ 分支逻辑全部保持原样）----
        // ★v221 兜底：execute 抛错时返回结构化错误回执，异常不冒泡到发送主流程——
        //   避免批次异常中断预览刷新与持久化、被外层 catch 误报为 API 错误（内容丢失链路成因之一）。
        let raw = null;
        let _execErr = null;
        if (_exec) {
          try { raw = _exec(ops, cd); }
          catch (_e) { raw = null; _execErr = _e; logWarn('opsPipeline.execute', _e); }
        }
        if (_execErr) {
          const _errLog = { _opErrors: ['⚠️【操作批次执行异常】' + (_execErr && _execErr.message ? _execErr.message : String(_execErr))] };
          return { ok: false, modified: false, changeLog: _errLog,
                   errors: [String(_execErr && _execErr.message || _execErr)], diff: null };
        }
        if (!raw) {
          return { ok: false, modified: false, changeLog: null,
                   errors: ['_opsPipeline: 未注入 execute（applyOps 为嵌套函数，顶层不可见——调用方必须传 ctx.execute）'],
                   diff: null };
        }
        // ---- post：时机敏感回调 → diff（含注入结果）→ 失败收集 → post hooks ----
        if (ctx && typeof ctx.afterExecute === 'function') {
          try { ctx.afterExecute(raw); } catch (e) { logWarn('opsPipeline.post.afterExecute', e); }
        }
        const modified = !!(raw && raw.modified);
        let diff = null;
        if (modified && _entriesBefore && _snap) {
          try { diff = computeEntryDiff(_entriesBefore, _snap()); } catch (e) { logWarn('opsPipeline.post.diff', e); }
        }
        const changeLog = raw && raw.changeLog ? raw.changeLog : null;
        const errors = [];
        if (changeLog) {
          (changeLog._opErrors || []).concat(changeLog._scriptEditFailures || []).forEach(function(e) { errors.push(String(e)); });
        }
        for (let _j = 0; _j < _hooks.post.length; _j++) {
          try { _hooks.post[_j]({ modified: modified, changeLog: changeLog, diff: diff, ops: ops }); } catch (e) { logWarn('opsPipeline.post.hook', e); }
        }
        // ---- result：冻结回执 ----
        const result = { ok: modified, modified: modified, changeLog: changeLog, errors: errors, diff: diff };
        try { Object.freeze(result); } catch (_) {}
        return result;
      }
    };
  })();

  function countTokens(text) {
    if (!text) return 0;
    const t = String(text);
    const cn = (t.match(RE_CJK) || []).length;
    const enWords = t.replace(RE_NON_CJK_SPLIT, ' ').split(/\s+/).filter(Boolean).length;
    return cn + Math.ceil(enWords * 0.75);
  }

