      if (gid && /^szxq-writer-/.test(String(gid)) && String(gid) !== _genId) return; // 只收本次生成的流
      const _ft = String(full_text || '');
      if (/<(thinking|reasoning|think)\s*>/i.test(_ft)) _sawThinkingInStream = true;
