      if (_stopHandle && typeof _stopHandle.stop === 'function') { try { _stopHandle.stop(); } catch (_s1) {} }
      if (_evtOff) { try { _evtOff(_evts.STREAM_TOKEN_RECEIVED_FULLY, _onStream); } catch (_s2) {} }
      _stopHandle = null;
