  // ===== 前端界面 HTML 基准模板（原 buildFrontendTabPrompt 内部常量，Agent 版提取为顶层供统一提示词引用）=====
  const FE_BEAUTIFY_BASE_HTML = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>正文美化</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: "Microsoft YaHei", sans-serif;
            background: transparent;
            padding: 8px;
        }

        .story-container {
            max-width: 650px;
            margin: 0 auto;
            padding: 24px 32px;
            line-height: 1.9;
            font-size: 15px;
            color: #d4d4d4;
        }

        /* 根据用户需求自由设计样式 */
        /* 例如：信纸效果、日记本效果、对话气泡等 */

        .loading {
            text-align: center;
            padding: 20px;
            color: #999;
        }
    </style>
</head>
<body>
    <div class="story-container" id="content">
        <div class="loading">正在加载...</div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                console.error("无法获取消息内容");
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 提取正文 ========== */
        function extractContent(messageText) {
            /* 注意这里的标签名要和正则里的保持一致 */
            var match = messageText.match(/<story>([\s\S]*?)<\/story>/);
            if (match && match[1]) {
                return match[1].trim();
            }
            return messageText;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(text) {
            /* 将换行转为段落 */
            var paragraphs = text.split(/\\n\\s*\\n/);
            var html = '';
            paragraphs.forEach(function(p) {
                var trimmed = p.trim();
                if (trimmed) {
                    /* 处理对话行和叙述行 */
                    if (trimmed.startsWith('"') || trimmed.startsWith('"') || trimmed.startsWith('「')) {
                        html += '<p class="dialogue">' + trimmed + '</p>';
                    } else {
                        html += '<p class="narrative">' + trimmed + '</p>';
                    }
                }
            });
            document.getElementById('content').innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML =
                        '<div class="loading">❌ 无法获取消息内容</div>';
                    return;
                }
                var text = extractContent(messageText);
                renderPage(text);
            } catch (error) {
                console.error("错误:", error);
                document.getElementById('content').innerHTML =
                    '<div class="loading">❌ 加载失败：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>`;
  const FE_STRUCTURED_BASE_HTML = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>页面标题</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: "Microsoft YaHei", sans-serif;
            background: transparent;
            padding: 8px;
        }

        .container {
            max-width: 600px;
            margin: 0 auto;
            border-radius: 12px;
            padding: 16px;
        }

        .loading {
            text-align: center;
            padding: 20px;
            color: #999;
        }

        /* 根据用户需求自由设计样式 */
    </style>
</head>
<body>
    <div class="container" id="content">
        <div class="loading">正在加载...</div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                console.error("无法获取消息内容");
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 解析数据 ========== */
        function parseData(messageText) {
            var result = {};

            /* 从完整消息中提取标签内容，注意替换为你的真实标签名 */
            var tagMatch = messageText.match(/<标签名>([\s\S]*?)<\/标签名>/);
            if (!tagMatch || !tagMatch[1]) {
                console.error("未找到标签内容");
                return result;
            }
            var content = tagMatch[1];

            /* 根据选用的数据格式进行解析 */
            /* 方式一：[字段|值] 格式的解析方式 */
            var match = content.match(/\[字段名\|([^\]]+)\]/);
            if (match && match[1]) {
                var parts = match[1].split('|');
                result.field1 = parts[0] || '';
                result.field2 = parts[1] || '';
            }

            /* 方式二：键值对格式的解析方式 */
            var lines = content.trim().split('\\n');
            lines.forEach(function(line) {
                var kv = line.split(':');
                if (kv.length >= 2) {
                    var key = kv[0].trim();
                    var value = kv.slice(1).join(':').trim();
                    result[key] = value;
                }
            });

            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(data) {
            var html = '';
            /* 根据用户需求构建HTML */
            document.getElementById('content').innerHTML = html;
        }

        /* ========== 交互函数 ========== */
        function handleClick(keyword, param) {
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send ' + keyword + '：' + param + '|/trigger');
            }
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML =
                        '<div class="loading">❌ 无法获取消息内容</div>';
                    return;
                }
                var data = parseData(messageText);
                renderPage(data);
            } catch (error) {
                console.error("错误:", error);
                document.getElementById('content').innerHTML =
                    '<div class="loading">❌ 加载失败：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>`;

  // ===== 0层卡前端聊天界面基准模板（界面内游玩模式：消息只在前端展示，不创建酒馆楼层）=====
  // 核心特点：
  //   1. 用户消息和AI回复都只在前端iframe界面内展示（气泡式聊天），不调用 createChatMessages 创建酒馆楼层
  //   2. ★v195 流式静默调用AI：window.parent.TavernHelper.generate，参数 should_stream:true /
  //      should_return_reasoning:true / disable_extras:true / stop_everything:true；监听
  //      STREAM_TOKEN_RECEIVED_FULLY 实时渲染，思维链体验对齐 DeepSeek：
