  //   3. 发送绑定：sendBtn.onclick = sendMessage + 回车发送（Enter 发送，Shift+Enter 换行）
  const FE_CHAT_BASE_HTML = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>聊天界面</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
            background: transparent;
            padding: 8px;
        }

        .chat-container {
            max-width: 650px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            height: 100%;
        }

        .messages {
            flex: 1;
            overflow-y: auto;
            padding: 12px 0;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .msg-row {
            display: flex;
            max-width: 85%;
            animation: fadeInUp 0.3s ease;
        }

        .msg-row.user {
            align-self: flex-end;
            flex-direction: row-reverse;
        }

        .msg-avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            color: #fff;
            margin: 0 8px;
        }

        .msg-row.user .msg-avatar {
            background: hsl(210, 60%, 50%);
        }

        .msg-row.assistant .msg-avatar {
            background: hsl(30, 60%, 50%);
        }

        .msg-bubble {
            padding: 10px 14px;
            border-radius: 16px;
            line-height: 1.7;
            font-size: 14px;
            word-break: break-word;
            white-space: pre-wrap;
        }

        .msg-row.user .msg-bubble {
            background: hsl(210, 60%, 45%);
            color: #fff;
            border-bottom-right-radius: 4px;
        }

        .msg-row.assistant .msg-bubble {
            background: hsla(0, 0%, 100%, 0.08);
            color: #e0e0e0;
            border-bottom-left-radius: 4px;
        }

        .msg-bubble.loading {
            opacity: 0.6;
            font-style: italic;
        }

        /* ★v196 思维链照抄 deepseek-harness ReasoningRow：💭思考 + running/ok + 流式摘要 + shimmer */
        .fe-think-head {
            position: relative;
            display: flex;
            align-items: center;
            height: 24px;
            min-width: 0;
            padding: 0 4px;
            border-radius: 6px;
            margin-bottom: 2px;
            user-select: none;
            cursor: pointer;
            color: #9a9a9a;
            font-size: 13px;
            line-height: 24px;
            transition: color .1s ease;
            overflow: hidden;
        }

        .fe-think-head:hover {
            color: #333;
        }

        .fe-think-ic {
            flex: none;
            width: 16px;
            height: 16px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            margin-right: 6px;
            color: inherit;
        }

        .fe-think-ic svg {
            width: 14px;
            height: 14px;
        }

        .fe-think-title {
            flex: none;
            font-size: 13px;
            line-height: 24px;
            color: inherit;
        }

        .fe-think-sep {
            flex: none;
            width: 2px;
            height: 2px;
            margin: 0 8px;
            border-radius: 1px;
            background: currentColor;
            opacity: .55;
        }

        .fe-think-summary {
            flex: 1 1 auto;
            min-width: 0;
            overflow: hidden;
            white-space: nowrap;
            font-size: 13px;
            line-height: 20px;
            color: inherit;
            text-overflow: ellipsis;
        }

        .fe-think-head[data-streaming] .fe-think-summary {
            mask-image: linear-gradient(to right, black calc(100% - 48px), transparent);
        }

        .fe-think-head[data-streaming] .fe-think-summary {
            overflow: visible;
            text-overflow: clip;
        }

        .fe-think-shine {
            position: absolute;
            inset: 0;
            pointer-events: none;
            overflow: hidden;
            border-radius: 6px;
        }

        .fe-think-shine::after {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(105deg, transparent 0%, rgba(255, 255, 255, .28) 40%, rgba(255, 255, 255, .28) 60%, transparent 100%);
            transform: translateX(-100%);
            animation: feShimmerSweep 1.5s steps(48) infinite;
            animation-delay: .3s;
        }

        .fe-think-head[data-state='ok'] .fe-think-shine {
            display: none;
        }

        @keyframes feShimmerSweep {
            0% {
                transform: translateX(-100%);
            }
            66.6667%,
            100% {
                transform: translateX(100%);
            }
        }

        @media (prefers-reduced-motion: reduce) {
            .fe-think-shine {
                display: none;
            }
        }

        .fe-think-body {
            font-size: 12px;
            line-height: 1.65;
            color: #9a9a9a;
            max-height: 240px;
            overflow-y: auto;
            padding: 4px 0 6px 22px;
            white-space: pre-wrap;
        }
            word-break: break-word;
        }

        .fe-stream-content {
            white-space: pre-wrap;
            word-break: break-word;
        }

        .input-area {
            display: flex;
            gap: 8px;
            padding-top: 12px;
            border-top: 1px solid hsla(0, 0%, 100%, 0.1);
        }

        #inputBox {
            flex: 1;
            min-height: 40px;
            max-height: 120px;
            padding: 10px 12px;
            border: 1px solid hsla(0, 0%, 100%, 0.15);
            border-radius: 10px;
            background: hsla(0, 0%, 100%, 0.05);
            color: #e0e0e0;
            font-size: 14px;
            font-family: inherit;
            resize: none;
            outline: none;
            line-height: 1.5;
        }

        #inputBox:focus {
            border-color: hsl(210, 60%, 50%);
        }

        #inputBox::placeholder {
            color: hsla(0, 0%, 100%, 0.3);
        }

        #sendBtn {
            width: 44px;
            height: 40px;
            border: none;
            border-radius: 10px;
            background: hsl(210, 60%, 50%);
            color: #fff;
            font-size: 18px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s;
            flex-shrink: 0;
        }

        #sendBtn:hover {
            background: hsl(210, 60%, 60%);
        }

        #sendBtn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(8px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
    </style>
</head>
<body>
    <div class="chat-container">
        <div class="messages" id="messages"></div>
        <div class="input-area">
            <textarea id="inputBox" placeholder="输入消息，Enter 发送，Shift+Enter 换行" rows="1"></textarea>
            <button id="sendBtn" title="发送">➤</button>
        </div>
    </div>

    <script>
        /* ========== 状态管理 ========== */
        var state = {
            character: null,      // 当前角色信息（从酒馆获取）
            messages: [],         // 聊天历史（内存中，不写入酒馆楼层）
            isGenerating: false   // 生成中标志
        };

        /* ========== DOM 引用 ========== */
        var dom = {
            messages: document.getElementById('messages'),
            inputBox: document.getElementById('inputBox'),
            sendBtn: document.getElementById('sendBtn')
        };

        /* ========== 渲染消息到前端界面 ========== */
        function renderMessage(role, content, isLoading) {
            var row = document.createElement('div');
            row.className = 'msg-row ' + role;

            var avatar = document.createElement('div');
            avatar.className = 'msg-avatar';
            avatar.textContent = role === 'user' ? '我' : 'AI';

            var bubble = document.createElement('div');
            bubble.className = 'msg-bubble' + (isLoading ? ' loading' : '');
            bubble.textContent = content;

            row.appendChild(avatar);
            row.appendChild(bubble);
            dom.messages.appendChild(row);

            // 滚动到底部
            dom.messages.scrollTop = dom.messages.scrollHeight;
            return bubble;
        }

        /* ========== 流式静默调用AI（不显示在酒馆聊天中） ==========
         * ★v195 核心：通过 window.parent.TavernHelper.generate 流式生成
         * 参数 should_stream:true / should_return_reasoning:true / disable_extras:true / stop_everything:true
         * 监听 iframe_events.STREAM_TOKEN_RECEIVED_FULLY(full_text, generation_id) 按 generation_id
         * 过滤实时回传，onStream(fullText) 逐段渲染；reasoning 用 <thinking> 包裹拼入最终文本。
         * 生成结果不创建酒馆楼层，只在前端界面展示
         */
        /* ★v196 deepseek-harness IconThinkOutlineRegular 思考图标（0 层卡版） */
        var FE_THINK_SVG =
            '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" stroke="currentColor" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
            '<path d="M10.2854 5.71481C12.9673 8.39663 14.1182 11.5938 12.8562 12.8559C11.5942 14.1179 8.39706 12.9669 5.71518 10.2851C3.03333 7.60323 1.88236 4.40608 3.14441 3.14403C4.40644 1.882 7.6036 3.03297 10.2854 5.71481Z"/>' +
            '<path d="M10.2854 10.2851C7.6036 12.9669 4.40644 14.1179 3.14441 12.8559C1.88236 11.5938 3.03333 8.39663 5.71518 5.71481C8.39706 3.03297 11.5942 1.882 12.8562 3.14403C14.1182 4.40608 12.9673 7.60323 10.2854 10.2851Z"/>' +
            '<path d="M8.86291 8.0002C8.86291 8.47549 8.47762 8.86087 8.00224 8.86087C7.52694 8.86087 7.1416 8.47549 7.1416 8.0002C7.1416 7.52485 7.52694 7.13953 8.00224 7.13953C8.47762 7.13953 8.86291 7.52485 8.86291 8.0002Z" fill="currentColor"/>' +
            '</svg>';
        /* deepseek-harness 折叠摘要逻辑：running 取「最新完成的段落首行」，done 取「第一行」 */
        function feFirstLine(text) {
            var nl = text.indexOf('\n');
            return nl === -1 ? text : text.slice(0, nl);
        }
        function feLatestCompletedParagraphFirstLine(text) {
            var summary = '', paragraphStart = 0;
            var separator = /\r?\n(?:[\t ]*\r?\n)+/g;
            while (true) {
                var nextParagraph = separator.exec(text);
                var paragraphEnd = nextParagraph === null ? text.length : nextParagraph.index + nextParagraph[0].indexOf('\n');
                var newline = text.indexOf('\n', paragraphStart);
                if (newline !== -1 && newline <= paragraphEnd) {
                    var candidate = text.slice(paragraphStart, newline).trim();
                    if (candidate !== '') summary = candidate;
                }
                if (nextParagraph === null) return summary;
                paragraphStart = nextParagraph.index + nextParagraph[0].length;
            }
        }
        async function callParentApi(promptToUse, onStream, useStream) {
            // ★v205 修复：useStream 参数控制是否流式（默认 true），与顶栏流式开关联动
            if (useStream === undefined) useStream = true;
            if (window.parent && window.parent.TavernHelper &&
                typeof window.parent.TavernHelper.generate === 'function') {
                var tavernGenerateFunc = window.parent.TavernHelper.generate;
                var evtOn = (typeof eventOn === 'function') ? eventOn :
                    (window.parent.eventOn ? window.parent.eventOn.bind(window.parent) : null);
                var evts = (typeof iframe_events !== 'undefined') ? iframe_events :
                    (window.parent.iframe_events || null);
                var genId = 'fe-chat-' + Date.now() + '-' + Math.floor(Math.random() * 9999);
                var stopHandle = null;
                var sawThinkingInStream = false; // ★v205 修复：流式正文里是否出现过 thinking 标签
                // ★复核修复（流式症状2-0层卡死）：fe 的 generate 原为裸调用（无任何超时），
                //   模型/后端挂起时 0 层界面永久 loading。补超时：
                //   ★用户要求取消 60s 空闲超时：流式模式（useStream=true）不再设任何时间限制，
                //   无限等待（慢思考/长停顿不被误杀），停止由用户/模型端决定；
                //   非流式模式（无活跃信号）保留固定 5 分钟预算防永久 loading。
                //   中止前尝试 stopGenerationById 真停止本次生成。
                var _feIdleTimer = null;
                var _feClearIdle = function() { if (_feIdleTimer) { clearInterval(_feIdleTimer); _feIdleTimer = null; } };
                var _feTimeoutWatch = null;
                if (!useStream) {
                    var _feDeadline = Date.now() + 300000;
                    _feTimeoutWatch = new Promise(function(_feRes, _feRej) {
                        _feIdleTimer = setInterval(function() {
                            if (Date.now() >= _feDeadline) {
                                clearInterval(_feIdleTimer);
                                _feIdleTimer = null;
                                try {
                                    if (window.parent && window.parent.TavernHelper &&
                                        typeof window.parent.TavernHelper.stopGenerationById === 'function') {
                                        window.parent.TavernHelper.stopGenerationById(genId);
                                    }
                                } catch (_feStopErr) {}
                                _feRej(new Error('生成超时（5分钟）'));
                            }
                        }, 3000);
                    });
                }
                if (useStream && evtOn && evts && evts.STREAM_TOKEN_RECEIVED_FULLY) {
                    try {
                        stopHandle = evtOn(evts.STREAM_TOKEN_RECEIVED_FULLY, function(fullText, gid) {
                            // ★修复（流式症状1-不流式）：与 callAIStream 同款放宽——仅确认是本次本机
                            //   生成的 ID（fe-chat- 前缀）且不匹配时才丢弃；其他回调参数格式一律放行，
                            //   避免版本差异导致领域规范同步"开了流式却不流式"。
                            if (gid && /^fe-chat-/.test(String(gid)) && String(gid) !== genId) return;
                            var ft = String(fullText || '');
                            if (/<(thinking|reasoning|think)\s*>/i.test(ft)) sawThinkingInStream = true;
                            if (onStream) onStream(ft);
                        });
                    } catch (e) { stopHandle = null; }
                }
                try {
                    var params = {
                        user_input: promptToUse,
                        should_stream: useStream,
                        should_return_reasoning: true,
                        disable_extras: true,
                        stop_everything: true,
                        generation_id: genId
                    };
                    var response;
                    try {
                        // ★用户要求取消 60s 空闲超时：流式模式直接 await（无限等待）；
                        //   仅非流式模式有 5 分钟固定预算（_feTimeoutWatch 存在时 race）。
                        response = _feTimeoutWatch
                            ? await Promise.race([tavernGenerateFunc(params), _feTimeoutWatch])
                            : await tavernGenerateFunc(params);
                        _feClearIdle();
                    } catch (err2) {
                        _feClearIdle();
                        throw err2;
                    }
                    if (stopHandle && typeof stopHandle.stop === 'function') { try { stopHandle.stop(); } catch (e) {} }
                    // 组装最终文本：reasoning → <thinking> 包裹（content 已带思维链标签则不重复包）
                    if (response && typeof response === 'object' && response.content !== undefined) {
                        var content = String(response.content || '');
                        var reasoning = response.reasoning ? String(response.reasoning) : '';
                        var hasTag = /<(thinking|reasoning|think)\s*>/i.test(content);
                        // ★v205 修复：原生 reasoning 回放——酒馆流式事件不透传 reasoning，若正文从未出现 thinking 标签，
                        //   把 reasoning 以打字机节奏回放给 onStream，实现思维链逐字流动（与 callAIStream 一致）
                        if (!sawThinkingInStream && reasoning && reasoning.trim().length > 0 && typeof onStream === 'function') {
                            var replayText = '<thinking>' + reasoning.trim() + '</thinking>';
                            var replayStep = Math.max(8, Math.round(replayText.length / 120));
                            await new Promise(function(resolve) {
                                var rp = 0;
                                var rpTimer = setInterval(function() {
                                    rp = Math.min(replayText.length, rp + replayStep);
                                    try { onStream(replayText.slice(0, rp)); } catch (_re) {}
                                    if (rp >= replayText.length) { clearInterval(rpTimer); resolve(); }
                                }, 16);
                            });
                        }
                        if (reasoning && !hasTag) return ('<thinking>' + reasoning + '</thinking>\n\n' + content).trim();
                        return content.trim();
                    }
                    return String(response || '').trim();
                } catch (err) {
                    if (stopHandle && typeof stopHandle.stop === 'function') { try { stopHandle.stop(); } catch (e2) {} }
                    throw err;
                }
            } else {
                // 没有 TavernHelper 时走本地模拟回复（开发调试用）
                console.warn('[聊天界面] TavernHelper 不可用，返回模拟回复');
                return '（模拟回复）收到你的消息：' + promptToUse;
            }
        }

        /* ========== 发送消息 ========== */
        // ★v205 斜杠命令系统（对标 deepseek-harness commands）：/xxx 直接执行，不发送给 AI
        var _SLASH_COMMANDS = {
          help: { desc: '显示所有可用命令', handler: function() {
            var cmds = Object.keys(_SLASH_COMMANDS).map(function(k){ return '/' + k + ' — ' + _SLASH_COMMANDS[k].desc; }).join('\n');
            renderMessage('assistant', '**可用斜杠命令：**\n\n' + cmds + '\n\n输入普通文本则正常对话。');
          }},
          clear: { desc: '清空对话历史（保留卡片数据）', handler: function() {
            state.messages = [];
            var c = document.getElementById('chatMessages');
            if (c) c.innerHTML = '';
            showToast('对话已清空', 'info', 2000);
          }},
          export: { desc: '导出当前角色卡为 JSON', handler: function() {
            try {
              var data = typeof getCardData === 'function' ? getCardData() : (window.__cardData || {});
              var blob = new Blob([JSON.stringify(data, null, 2)], {type: 'application/json'});
              var url = URL.createObjectURL(blob);
              var a = document.createElement('a');
              a.href = url; a.download = 'character_card.json'; a.click();
              URL.revokeObjectURL(url);
              showToast('卡片已导出', 'success', 2000);
            } catch(e) { showToast('导出失败: ' + e.message, 'error', 3000); }
          }},
          reset: { desc: '重置卡片到初始状态', handler: function() {
            if (window.confirm('确定要重置卡片吗？所有未导出的修改将丢失。')) {
              try {
                if (typeof resetCardData === 'function') resetCardData();
                state.messages = [];
                var c = document.getElementById('chatMessages');
                if (c) c.innerHTML = '';
                showToast('卡片已重置', 'info', 2000);
              } catch(e) { showToast('重置失败: ' + e.message, 'error', 3000); }
            }
          }},
          theme: { desc: '切换明暗主题', handler: function() {
            try {
              var cur = document.documentElement.getAttribute('data-theme') || 'light';
              var next = cur === 'light' ? 'dark' : 'light';
              document.documentElement.setAttribute('data-theme', next);
              localStorage.setItem('cw-theme', next);
              showToast('已切换到' + (next === 'dark' ? '暗色' : '亮色') + '主题', 'info', 1500);
            } catch(e) {}
          }},
          compact: { desc: '手动压缩对话历史', handler: function() {
            try {
              if (typeof window.__cwManualCompact === 'function') window.__cwManualCompact();
              else showToast('压缩功能不可用', 'error', 2000);
            } catch(e) { showToast('压缩失败: ' + e.message, 'error', 3000); }
          }},
          status: { desc: '显示当前会话状态', handler: function() {
            var msgs = state.messages ? state.messages.length : 0;
            var gen = state.isGenerating ? '生成中' : '空闲';
            var tab = window.__tab_activeTab || 'card';
            renderMessage('assistant', '**会话状态**\n\n- 消息数：' + msgs + '\n- 状态：' + gen + '\n- 当前Tab：' + tab + '\n- 版本：' + (typeof CARDER_VERSION !== 'undefined' ? CARDER_VERSION : 'unknown'));
          }},
          stop: { desc: '停止当前生成', handler: function() {
            try {
              window.__cwAbortRequested = true;
              if (typeof window.__cwCurrentGenId !== 'undefined' && window.__cwCurrentGenId && typeof requestAbort === 'function') {
                requestAbort(window.__cwCurrentGenId);
              }
              showToast('已请求停止', 'info', 1500);
            } catch(e) {}
          }}
        };
        async function sendMessage() {
            var text = dom.inputBox.value.trim();
            if (!text || state.isGenerating) return;

            // ★v205 斜杠命令检测：/xxx 格式直接执行，不发送给 AI
            if (text.charAt(0) === '/' && text.length > 1) {
              var _cmdMatch = text.match(/^\/([a-z]+)(?:\s+(.*))?$/i);
              if (_cmdMatch) {
                var _cmd = _cmdMatch[1].toLowerCase();
                var _arg = _cmdMatch[2] || '';
                if (_SLASH_COMMANDS[_cmd]) {
                  dom.inputBox.value = '';
                  dom.inputBox.style.height = 'auto';
                  try { _SLASH_COMMANDS[_cmd].handler(_arg); } catch(_ce) { showToast('命令执行失败: ' + _ce.message, 'error', 3000); }
                  return;
                } else {
                  showToast('未知命令: /' + _cmd + '（输入 /help 查看可用命令）', 'error', 3000);
                  return;
                }
              }
            }

            // 1. 清空输入框
            dom.inputBox.value = '';
            dom.inputBox.style.height = 'auto';

            // 2. 渲染用户消息（只在前端界面展示）
            renderMessage('user', text);
            state.messages.push({ role: 'user', content: text });

            // 3. 显示AI加载中 → ★v196 流式预览（deepseek-harness ReasoningRow：💭思考 + 摘要 + running/ok）
            state.isGenerating = true;
            dom.sendBtn.disabled = true;
            var aiRow = renderMessage('assistant', '', false);
            var bubble = aiRow.querySelector('.msg-bubble') || aiRow;
            var thinkHead = document.createElement('div');
            thinkHead.className = 'fe-think-head';
            thinkHead.setAttribute('data-state', 'running');
            thinkHead.innerHTML = '<span class="fe-think-ic">' + FE_THINK_SVG + '</span>' +
                '<span class="fe-think-title">思考</span>' +
                '<span class="fe-think-sep"></span>' +
                '<span class="fe-think-summary"></span>' +
                '<span class="fe-think-shine"></span>';
            var thinkSum = thinkHead.querySelector('.fe-think-summary');
            var thinkSep = thinkHead.querySelector('.fe-think-sep');
            var thinkBody = document.createElement('div');
            thinkBody.className = 'fe-think-body';
            thinkBody.style.display = 'none';
            var contentEl = document.createElement('div');
            contentEl.className = 'fe-stream-content';
            bubble.appendChild(thinkHead);
            bubble.appendChild(thinkBody);
            bubble.appendChild(contentEl);
            var streamState = { bodyOpen: false };
            // ★v196 流式摘要：running 取最新完成段落首行，done 取第一行（deepseek-harness）
            function feUpdateSummary() {
                if (!thinkSum) return;
                var t = thinkBody.textContent || '';
                var sum = '';
                if (inThinking) sum = feLatestCompletedParagraphFirstLine(t);
                else if (thinkBody._done) sum = feFirstLine(t);
                thinkSum.textContent = sum.replace(/\*\*/g, '');
                thinkSum.style.display = sum ? '' : 'none';
                if (thinkSep) thinkSep.style.display = sum ? '' : 'none';
            }
            // 点击整行切换展开/收起（deepseek-harness expandOnRowClick）
            thinkHead.onclick = function() {
                streamState.bodyOpen = !streamState.bodyOpen;
                thinkBody.style.display = streamState.bodyOpen ? 'block' : 'none';
                if (streamState.bodyOpen) thinkBody.scrollTop = thinkBody.scrollHeight;
            };
            var inThinking = false, prevLen = 0, prevFull = '';
            // ★修复（流式症状4-思考卡顿）：0 层 fe 同款时间闸——记录最近一次流式事件到达时刻，
            //   feFlush 死锁保护据此判断流式是否真的还在继续（5s 无新事件 → 强制刷残留，不再无限 rAF 空转）。
            var feLastFeedAt = 0;
            // ★v195 平滑流式：增量缓冲 + requestAnimationFrame 自适应刷帧（既平滑又快）
            var streamBuf = '', feRafId = null, feStreaming = true, feFrame = 0;
            var FE_OPEN_RE = /<(thinking|reasoning|think)\s*>/i;
            var FE_CLOSE_RE = /<\/(thinking|reasoning|think|redacted_reasoning)>/i;
            var FE_TAG_PREFIXES = ['<thinking', '<reasoning', '<think', '</thinking', '</reasoning', '</think', '</redacted_reasoning'];
            function feIsTagPrefix(s) {
                if (!s || s.charAt(0) !== '<') return false;
                if (s.indexOf('>') >= 0) return false;
                for (var i = 0; i < FE_TAG_PREFIXES.length; i++) {
                    if (FE_TAG_PREFIXES[i].indexOf(s) === 0) return true;
                }
                return false;
            }
            // 状态机：返回未消费的半截标签前缀（放回缓冲等下一帧累积完整）
            function feApplyDelta(delta) {
                if (!delta) return '';
                var rest = delta;
                while (rest.length > 0) {
                    if (!inThinking) {
                        var m = rest.match(FE_OPEN_RE);
                        if (m) {
                            if (m.index > 0) contentEl.textContent += rest.slice(0, m.index);
                            inThinking = true;
                            // ★v196 running 态：💭思考 + 流式摘要 + shimmer（body 默认折叠，点击展开）
                            thinkHead.setAttribute('data-state', 'running');
                            thinkHead.setAttribute('data-streaming', '');
                            thinkBody.classList.remove('fe-think-done');
                            rest = rest.slice(m.index + m[0].length);
                            continue;
                        }
                        var ltIdx = rest.indexOf('<');
                        if (ltIdx >= 0) {
                            if (ltIdx > 0) {
                                contentEl.textContent += rest.slice(0, ltIdx);
                                // ★v196 正文已出且从未思考 → 隐藏思考行
                                if (!inThinking && !thinkBody._done) thinkHead.style.display = 'none';
                            }
                            var tail = rest.slice(ltIdx);
                            if (feIsTagPrefix(tail)) return tail;
                            contentEl.textContent += tail;
                            rest = '';
                        } else {
                            contentEl.textContent += rest;
                            // ★v196 正文已出且从未思考 → 隐藏思考行
                            if (!inThinking && !thinkBody._done) thinkHead.style.display = 'none';
                            rest = '';
                        }
                    } else {
                        var c = rest.match(FE_CLOSE_RE);
                        if (c) {
                            thinkBody.textContent += rest.slice(0, c.index);
                            inThinking = false;
                            thinkBody._done = true;
                            // ★v196 ok 态：💭思考 + 第一行摘要 + 自动折叠（点击展开完整思考内容）
                            thinkHead.setAttribute('data-state', 'ok');
                            thinkHead.removeAttribute('data-streaming');
                            thinkBody.classList.add('fe-think-done');
                            streamState.bodyOpen = false;
                            thinkBody.style.display = 'none';
                            rest = rest.slice(c.index + c[0].length);
                            feUpdateSummary();
                            continue;
                        }
                        var ltIdx2 = rest.indexOf('<');
                        if (ltIdx2 >= 0) {
                            if (ltIdx2 > 0) thinkBody.textContent += rest.slice(0, ltIdx2);
                            var tail2 = rest.slice(ltIdx2);
                            if (feIsTagPrefix(tail2)) return tail2;
                            thinkBody.textContent += tail2;
                            feUpdateSummary();  // ★v196 流式摘要随思维链逐帧刷新
                            rest = '';
                        } else {
                            thinkBody.textContent += rest;
                            feUpdateSummary();  // ★v196 流式摘要随思维链逐帧刷新
                            rest = '';
                        }
                    }
                }
                return '';
            }
            function feFlush() {
                feRafId = null;
                if (streamBuf.length > 0) {
                    var beforeLen = streamBuf.length;
                    var chunkSize = Math.min(streamBuf.length, Math.max(2, Math.ceil(streamBuf.length / 6)));
                    // 防标签切断：chunk 末尾是半截前缀时扩大到下一个 >
                    var probe = streamBuf.slice(0, chunkSize);
                    var lastLt = probe.lastIndexOf('<');
                    if (lastLt >= 0) {
                        var tail = probe.slice(lastLt);
                        if (feIsTagPrefix(tail)) {
                            var gtIdx = streamBuf.indexOf('>', chunkSize);
                            chunkSize = (gtIdx >= 0) ? gtIdx + 1 : streamBuf.length;
                        }
                    }
                    var chunk = streamBuf.slice(0, chunkSize);
                    var leftover = feApplyDelta(chunk);
                    streamBuf = leftover + streamBuf.slice(chunkSize);
                    // ★思维链输出时自动滚动 body 内部到底部（跟随最新内容）
                    if (inThinking) thinkBody.scrollTop = thinkBody.scrollHeight;
                    // 死锁保护（最后兜底）：流式进行中跳过本帧等新内容；流式结束后强制输出
                    // ★修复（流式症状4-思考卡顿）：同款时间闸——流式事件已停但 await 未返回时，
                    //   原逻辑会无限 rAF 空转（CPU 空耗）；5s 无新事件视为流式结束，强制刷残留。
                    if (streamBuf.length === beforeLen && streamBuf.length > 0) {
                        if (!feStreaming || (feLastFeedAt && Date.now() - feLastFeedAt > 5000)) {
                            var ch = streamBuf.charAt(0);
                            if (inThinking) thinkBody.textContent += ch; else contentEl.textContent += ch;
                            streamBuf = streamBuf.slice(1);
                        }
                    }
                }
                feFrame++;
                // ★v196 仅思维链跟随滑动条：思维链输出阶段自动滚到最底，正文打字机阶段不强制滚动
                if (feFrame % 2 === 0 && inThinking) dom.messages.scrollTop = dom.messages.scrollHeight;
                if (feStreaming || streamBuf.length > 0) feRafId = requestAnimationFrame(feFlush);
            }

            // 4. 流式调用AI（思维链状态机增量渲染 + 缓冲平滑）
            try {
                // 拼接提示词：聊天历史 + 当前用户消息
                var prompt = buildPrompt(state.messages);
                // ★v205 修复：与顶栏流式开关联动，关闭时走非流式
                var _useStream = (typeof getStreamMode === 'function') ? getStreamMode() !== 'off' : true;
                var aiResponse = await callParentApi(prompt, function(fullText) {
                    var t = String(fullText || '');
                    feLastFeedAt = Date.now();  // ★修复（流式症状4）：任意事件到达刷新活跃戳
                    if (t === prevFull) return;
                    var delta = t.slice(prevLen);
                    prevLen = t.length;
                    prevFull = t;
                    if (delta) streamBuf += delta;
                    if (feRafId == null && (feStreaming || streamBuf.length > 0)) feRafId = requestAnimationFrame(feFlush);
                }, _useStream);

                // 5. 最终渲染：完整文本分区（思维链折叠「💭思考」首行摘要 + 正文）
                renderFinalResponse(aiResponse, thinkHead, thinkBody, contentEl, streamState);
                bubble.classList.remove('loading');
                state.messages.push({ role: 'assistant', content: aiResponse });
            } catch (err) {
                bubble.classList.remove('loading');
                contentEl.textContent = '⚠️ 生成失败：' + err.message;
            } finally {
                feStreaming = false;
                if (feRafId != null) { cancelAnimationFrame(feRafId); feRafId = null; }
                if (streamBuf.length > 0) { feApplyDelta(streamBuf); streamBuf = ''; }
                state.isGenerating = false;
                dom.sendBtn.disabled = false;
                // ★v205 ContextMeter：消息完成后更新上下文占用率
                try { if (typeof updateContextMeter === 'function') updateContextMeter(); } catch (_) {}
            }
        }

        /* ========== 最终回复渲染：思维链自动折叠「思考」（💭+首行摘要，可展开）+ 正文 ========== */
        function renderFinalResponse(text, thinkHead, thinkBody, contentEl, streamState) {
            var t = String(text || '');
            var thM = t.match(/<\s*(thinking|reasoning|think)\s*>([\s\S]*?)<\s*\/(?:thinking|reasoning|think|redacted_reasoning)\s*>/i);
            var contentText = t;
            if (thM) {
                thinkBody.textContent = thM[2];
                thinkBody._done = true;
                // ★v196 deepseek-harness ok 态：💭思考 + 第一行摘要 + 自动折叠（点击展开完整思考内容）
                streamState.bodyOpen = false;
                thinkHead.setAttribute('data-state', 'ok');
                thinkHead.removeAttribute('data-streaming');
                thinkBody.classList.add('fe-think-done');
                thinkBody.style.display = 'none';
                if (typeof feUpdateSummary === 'function') feUpdateSummary();
                else {
                    var _fsum = thinkHead.querySelector('.fe-think-summary');
                    if (_fsum) _fsum.textContent = feFirstLine(thM[2]).replace(/\*\*/g, '');
                }
                contentText = t.replace(thM[0], '').trim();
            } else {
                thinkHead.style.display = 'none';
                thinkBody.style.display = 'none';
            }
            contentEl.textContent = contentText;
            dom.messages.scrollTop = dom.messages.scrollHeight;
        }

        /* ========== 构建提示词（聊天历史 + 系统提示） ========== */
        function buildPrompt(history) {
            // 这里可以拼接角色设定、系统提示、聊天历史
            // 简化版：直接把最近几条消息拼成对话
            var parts = [];
            history.forEach(function(msg) {
                parts.push((msg.role === 'user' ? '用户：' : 'AI：') + msg.content);
            });
            return parts.join('\\n\\n');
        }

        /* ========== 绑定发送事件 ========== */
        dom.sendBtn.onclick = sendMessage;

        dom.inputBox.onkeydown = function(e) {
            // Enter 发送，Shift+Enter 换行
            if (e.key === 'Enter' && !e.shiftKey && state.character) {
                e.preventDefault();
                sendMessage();
            }
        };

        // 输入框自适应高度
        dom.inputBox.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 120) + 'px';
        });

        /* ========== 初始化 ========== */
        function init() {
            // 获取当前角色信息（从酒馆）
            try {
                if (window.parent && window.parent.TavernHelper) {
                    // 可以在这里获取角色设定、世界书等信息
                    state.character = { name: '角色' };
                }
            } catch (e) {
                console.warn('[聊天界面] 初始化失败：', e);
            }

            // 显示欢迎消息
            renderMessage('assistant', '你好！我是你的AI伙伴，有什么想聊的吗？');
        }

        $(function() { init(); });
    </script>
</body>
</html>`;

  // ===== 意图分类规则（顶层常量，避免每轮 buildPrompt 重建对象）=====
