      // ============================================================================
      // SECTION 9  持久化 & 酒馆 SillyTavern API 适配层
      // ============================================================================
      // ===== localStorage 持久化 =====
      const STORAGE_KEY = 'modelo_char_generator_agent_state'; // Agent版独立存档key：避免与旧三Tab版存档互相覆盖（旧key: modelo_char_generator_state）

      // ★v223 Fix-15：存储扩容——localStorage 单键 5MB 上限（桌面/移动端浏览器同此限制），
      //   大卡（超大世界书/长会话/AI多轮上下文）存不下会丢失进度。
      //   新增 IndexedDB 持久层（桌面/移动端浏览器配额通常远大于 5MB，且不弹配额提示）：
      //   · 保存：local 成功 → 异步双写 IDB（幂等备份）；local 超限（含精简重试失败）
      //     → 完整 state 写 IDB + local 写指针（:ptr），下次恢复走 IDB
      //   · 加载：local 优先（同步兼容现状）；local 无全量但指针存在 → 异步从 IDB 回填再恢复
      //   · 清空：开新卡 clearStorage 同步清 local + 指针 + IDB，保证"开新卡清干净"
      const _IDB = (function() {
        let _db = null, _openPromise = null;
        const DB_NAME = 'my_carder_db';
        const STORE_NAME = 'state';
        function _open() {
          if (_db) return Promise.resolve(_db);
          if (_openPromise) return _openPromise;
          _openPromise = new Promise(function(resolve, reject) {
            try {
              if (typeof indexedDB === 'undefined') { reject(new Error('no-indexeddb')); return; }
              const req = indexedDB.open(DB_NAME, 1);
              req.onupgradeneeded = function() {
                try {
                  const db = req.result;
                  if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
                } catch (_) {}
              };
              req.onsuccess = function() { _db = req.result; resolve(_db); };
              req.onerror = function() { reject(req.error || new Error('idb-open-error')); };
              req.onblocked = function() { /* 等旧连接释放 */ };
            } catch (e) { reject(e); }
          }).catch(function(_e) { _openPromise = null; throw _e; });
          return _openPromise;
        }
        return {
          set: function(key, value) {
            try {
              return _open().then(function(db) {
                return new Promise(function(resolve) {
                  try {
                    const tx = db.transaction(STORE_NAME, 'readwrite');
                    tx.objectStore(STORE_NAME).put(value, key);
                    tx.oncomplete = function() { resolve(true); };
                    tx.onerror = function() { resolve(false); };
                    tx.onabort = function() { resolve(false); };
                  } catch (_) { resolve(false); }
                });
              });
            } catch (_) { return Promise.resolve(false); }
          },
          get: function(key) {
            try {
              return _open().then(function(db) {
                return new Promise(function(resolve) {
                  try {
                    const tx = db.transaction(STORE_NAME, 'readonly');
                    const rq = tx.objectStore(STORE_NAME).get(key);
                    rq.onsuccess = function() { resolve(rq.result); };
                    rq.onerror = function() { resolve(undefined); };
                  } catch (_) { resolve(undefined); }
                });
              });
            } catch (_) { return Promise.resolve(undefined); }
          },
          del: function(key) {
            try {
              return _open().then(function(db) {
                return new Promise(function(resolve) {
                  try {
                    const tx = db.transaction(STORE_NAME, 'readwrite');
                    tx.objectStore(STORE_NAME).delete(key);
                    tx.oncomplete = function() { resolve(true); };
                    tx.onerror = function() { resolve(false); };
                    tx.onabort = function() { resolve(false); };
                  } catch (_) { resolve(false); }
                });
              });
            } catch (_) { return Promise.resolve(false); }
          },
          clear: function() {
            try {
              return _open().then(function(db) {
                return new Promise(function(resolve) {
                  try {
                    const tx = db.transaction(STORE_NAME, 'readwrite');
                    tx.objectStore(STORE_NAME).clear();
                    tx.oncomplete = function() { resolve(true); };
                    tx.onerror = function() { resolve(false); };
                    tx.onabort = function() { resolve(false); };
                  } catch (_) { resolve(false); }
                });
              });
            } catch (_) { return Promise.resolve(false); }
          }
        };
      })();
      const _IDB_PTR_KEY = STORAGE_KEY + ':ptr'; // local 指针：全量存档在 IDB 时置 '1'，恢复后删除

      // ★v223 Fix-15：异步从 IndexedDB 恢复大卡存档——local 无全量但指针存在时调用。
      //   流程：读 IDB 全量 → 回填 local（后续 saveToStorage 双写保持同步）→ 删指针 → 走 continueFromSave
      function restoreFromIdb() {
        try {
          const _ptr = localStorage.getItem(_IDB_PTR_KEY);
          if (!_ptr) return false;
          _IDB.get(STORAGE_KEY).then(function(raw) {
            try {
              if (raw && typeof raw === 'string' && raw.length > 0) {
                localStorage.setItem(STORAGE_KEY, raw);
                localStorage.removeItem(_IDB_PTR_KEY);
                console.warn('[storage] ★v223 已从扩展存储(IndexedDB)恢复大卡存档（localStorage 5MB 装不下）');
                if (typeof continueFromSave === 'function') {
                  try { continueFromSave(); } catch (_cErr) { logWarn('idbRestore', _cErr); }
                }
              } else {
                localStorage.removeItem(_IDB_PTR_KEY); // 指针残留但数据不在 → 清指针防死循环
              }
            } catch (_applyErr) { logWarn('idbRestore.apply', _applyErr); }
          });
          return true;
        } catch (_e) { logWarn('idbRestore', _e); return false; }
      }

      // ===== 创建全新空 cardData 对象（写新卡/新建工作区时用，保证彻底无旧值残留）=====
