            const _rdRes = _readLinesWithNumbers(scripts[sFoundIdx].content || '',
              _rdLm ? _rdLm[1] : 1, _rdLm && _rdLm[2] ? _rdLm[2] : null, 60);
            // ★v197 harness 观察策略：#1 先读才能改的数据源——read 登记"已见 + 版本戳"
